UPDATE gaps SET
  status='CLOSED-RESOLVED',
  description=description || ' || CLOSED 2026-07-25 (batch 2). Independence CONFIRMED, gap does not hold. Five independent groups in six countries associate rest/bench provision with walking outcomes, none Finnish and none sharing authors with the Jyvaskyla cluster: REF-00955 (CA, GPS-measured routes), REF-00956 (CZ, n=525 survey), REF-00957 (FR, spatial accessibility model), REF-00958 (HK, qualitative), REF-00959 (US, n=3,677, benches retained through empirical item selection into a validated instrument). The methods are independent of one another as well as the authors, so this is not one finding echoed five times.',
  updated_at='2026-07-25', updated_by_session='session_2026-07-25-energy-conservation-rest-points-seating-b2'
WHERE gap_id='GAP-306';

UPDATE gaps SET
  description=description || ' || SHARPENED 2026-07-25 (batch 2), still OPEN and now better evidenced as a real hole. Six further sources were read (REF-00953..00959) including a participatory national framework (REF-00954) and a validated US instrument at n=3,677 (REF-00959). NOT ONE states a spacing figure. REF-00954 declines to give a number even though disabled street users were consulted directly; REF-00959 records bench PRESENCE only. So bench presence is repeatedly and independently associated with walking outcomes, while the INTERVAL remains unmeasured by anyone. The 50m figure is not merely under-evidenced - the entire literature that supports rest provision is silent on spacing.',
  updated_at='2026-07-25', updated_by_session='session_2026-07-25-energy-conservation-rest-points-seating-b2'
WHERE gap_id='GAP-304';

INSERT INTO gaps (gap_id, category, priority, status, skill, section, description,
                  falsification_condition, created_at, created_by_session,
                  updated_at, updated_by_session, mining_addressability)
VALUES
 ('GAP-307','EG','P1','OPEN','item-specification-writer','energy-conservation-rest-points-seating',
  'SINGLE-HEIGHT SEATING IS AN EQUITY HARM AND THE STANDARD ENCODES IT. REF-00953 audited 410-505mm seat heights across facilities and 423-510mm across suppliers and found NONE would fit a 5th-percentile older Australian female (popliteal height 330mm vs population mean 379mm). The consequence is not discomfort alone: "shorter residents are being disadvantaged compared with taller ones, suffering discomfort and possible musculoskeletal damage while sitting and being put at risk of deep venous thrombosis (DVT) due to the seating design", and the harm is GENDERED because women are 69% of permanent aged care in Australia and are likelier to be shorter. UK DfT Inclusive Mobility p.102 specifies a single 470-480mm band for the majority of seats, which sits inside the range REF-00953 found excludes short users. The Co-1 source REF-00950 independently specifies plural heights (380/480/580mm). Best practice for this slug should therefore be a RANGE of heights per location, not a single value.',
  'Falsified if a study finds a single seat height that accommodates sit-to-stand for low-strength users AND seated comfort for 5th-percentile stature simultaneously, or if the DVT/musculoskeletal harm attributed to over-high seating fails to replicate.',
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','ADDRESSABLE'),

 ('GAP-308','EG','P2','OPEN','multilingual-research','energy-conservation-rest-points-seating',
  'REST POINTS MUST BE ANTICIPATABLE, AND NO SPECIFICATION CAPTURES THIS. REF-00954 records disabled street users requiring that seating "be positioned so that it is possible to see from a distance i.e. to allow journey planning" and be "clearly signposted ... to allow them to know when to anticipate potential for breaks in their journey". Neither REF-00949 (DfT) nor REF-00950 (Wheels for Wellbeing) specifies visibility, sightline or signage of rest points; both specify only provision and setback. A rest point that cannot be seen or anticipated does not support the decision to ATTEMPT the journey, so provision alone under-specifies the demand. No parameter exists anywhere in the corpus for rest-point visibility or wayfinding.',
  'Falsified if a standard or primary study is found specifying sightline, visibility distance or signage requirements for rest points.',
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','ADDRESSABLE'),

 ('GAP-309','RP','P3','OPEN','citation-verifier','energy-conservation-rest-points-seating',
  'TWO SLUG-RELEVANT SOURCES ARE LOCATOR-BLOCKED TO THIS TOOLCHAIN. Transport for All "Are We There Yet?" (2023) returned HTTP 403 on all three routes tried (highlights PDF, full PDF, HTML news page); Ulahannan et al. "Inclusive Streetscapes" returned HTTP 403 from sciencedirect.com and has no DOI recorded from the engine that surfaced it. Both are potentially Co-1 or Co-1-adjacent UK lived-experience sources, i.e. exactly the evidence class this slug is thinnest in - the slug currently holds ONE Co-1 source. Neither may be admitted on secondary description.',
  'Falsified when either source is retrieved through any working route and re-described from the source itself.',
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','ADDRESSABLE');

-- ---------- R2 citation mining register ----------
UPDATE citation_mining SET
  forward=1, connections_produced=5, deferred_reason=NULL,
  notes='FORWARD MINING EXECUTED 2026-07-25 (batch 2) - this was batch 1 highest-value deferred target and it resolved GAP-306. Rather than walking citations one by one, the independence question was attacked directly with a well-formed topical query designed to surface groups OTHER than the Finnish cluster. 5 connections produced (REF-00955..00959) across six countries and five distinct methods. Deliberate design point: an adversarial construction was preferred to a citation walk precisely because a citation walk from a Finnish-cluster paper tends to return the same cluster. Supersedes the batch-1 deferral on this row.',
  updated_at='2026-07-25', updated_by_session='session_2026-07-25-energy-conservation-rest-points-seating-b2'
WHERE slug='energy-conservation-rest-points-seating' AND local_ref_id='ECR-03';

INSERT INTO citation_mining
 (slug, local_ref_id, global_ref_id, doi, backward, forward, connections_produced, notes,
  created_at, created_by_session, updated_at, updated_by_session, deferred_reason)
VALUES
 ('energy-conservation-rest-points-seating','ECR-09','REF-00953','10.1177/2050312117744925',1,0,0,
  'BACKWARD MINING PARTIAL. Its literature review was read closely and yields named further anchors - Christenson (380-457mm variety recommendation), Holden and Fernie (armrest 730mm from floor, 250mm above seat, 120mm width), Kothiyal and Tettey (seat depth 376mm), Scarborough et al. (chair-rise strategies), and the Australian Standard for fixed-height chairs (380-480mm effective seat depth). NONE resolved to a locator this batch, so 0 connections produced rather than counting them as found. These are the batch-3 backward queue and are the likeliest route to a primary derivation for the dimensional figures.',
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2',NULL),
 ('energy-conservation-rest-points-seating','ECR-15','REF-00959',NULL,0,0,0,NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2',
  'DEFERRED WITH REASON. REF-00959 (MAPS-Mini) is highly cited and its forward graph is large, but it is an instrument-validation paper: forward citations will mostly be studies USING the instrument rather than studies measuring rest-point spacing. Mining it would produce volume without addressing GAP-304. Queued behind the REF-00953 backward leads, which bear directly on the open dimensional question.'),
 ('energy-conservation-rest-points-seating','ECR-10','REF-00954',NULL,1,0,0,NULL,
  '2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2','2026-07-25','session_2026-07-25-energy-conservation-rest-points-seating-b2',
  'DEFERRED WITH REASON. Appendix C is one appendix of a larger Transport Scotland publication; the parent report and its other appendices were not enumerated this batch. Worth a targeted pass in batch 3 since the parent may carry the specification detail the appendix omits - including, possibly, the interval figure the appendix declines to state.');


-- Closing a research gap requires the full protocol field set, not just a falsification
-- condition (research_protocol_audit CHECK 1). Recording what would shift the conclusion and
-- who could reasonably dissent is the point of closing a gap rather than deleting it.
UPDATE gaps SET
  confidence_interval='80-90%',
  shift_conditions='The 80-90% is confidence that the association is not an artefact of ONE research group; it is NOT a claim about effect magnitude, which none of these sources was designed to estimate and which this closure does not assert. Would reopen if the independent sources were found to share an unrecognised common origin (e.g. all deriving their bench variable from one prior instrument), or if a well-powered study found no association between rest provision and walking outcomes in a population with elevated sustained-exertion demand.',
  named_dissenter='No source located disputes the association. The honest counterweight is internal: REF-00955 is n=25 and self-described as exploratory, REF-00958 is n=38 qualitative, and REF-00957 enrolled no participants at all - so breadth of replication is doing the work here, not depth of any single study. A reviewer could fairly argue that five weak-to-moderate studies agreeing is weaker than it looks; the response is that they agree across methods that fail in different directions.',
  updated_at='2026-07-25', updated_by_session='$S'
WHERE gap_id='GAP-306';

